const errorData = $input.first().json;

const incident = {
  severity: 'CRITICAL',
  workflowId: errorData.workflow?.id || 'unknown',
  workflowName: errorData.workflow?.name || 'LendLoop Workflow',
  executionId: errorData.execution?.id || 'unknown',
  failedNode: errorData.execution?.lastNodeExecuted || 'unknown',
  errorMessage: errorData.execution?.error?.message || errorData.message || 'Unknown automation execution failure',
  timestamp: new Date().toISOString(),
  environment: $env.NODE_ENV || 'production'
};

console.error(`[LendLoop Automation Incident] FAILED WORKFLOW: "${incident.workflowName}" | NODE: "${incident.failedNode}"`);
console.error(`ERROR DETAILS: ${incident.errorMessage}`);
console.error(`EXECUTION ID: ${incident.executionId}`);

return [{
  json: incident
}];

const incident = $input.first().json;

// Emits simulated operational alert (can be configured to PagerDuty/Discord/Slack/Email)
console.log(`[ALERT DISPATCHED] Operational incident recorded for workflow "${incident.workflowName}". Preventing silent failures.`);

return [{
  json: {
    incidentRecorded: true,
    workflow: incident.workflowName,
    loggedAt: incident.timestamp
  }
}];
